insert into routes (id, area_id, name, discipline, grade, grade_system, description) values
  ('ca_owens_peak_indian_wells_canyon', 'ca_owens_peak', 'Indian Wells Canyon', 'scrambling', 'Class 2', 'class', 'Follow the old road to a wilderness barricade, then a canyon trail to a clearing near 6,100 ft. Take the right fork on a use trail through dark boulders and finish up slabs; about 7 miles round trip with 3,200 ft of gain.'),
  ('ca_rockhouse_peak_standard_route', 'ca_rockhouse_peak', 'Standard route', 'scrambling', 'Class 2', 'class', null),
  ('ca_smith_mountain_albanita_trail_and_northeast_ridge', 'ca_smith_mountain', 'Albanita Trail and Northeast Ridge', 'scrambling', 'Class 2', 'class', 'Follow an old road onto the Albanita Trail to a saddle on the northeast ridge, then go cross-country past a granite crag to the rocky summit. About 3.3 miles round trip with 1,100 ft of gain and a short exposed scramble at the end.'),
  ('ca_north_maggie_mountain_saddle_route_from_long_meadow', 'ca_north_maggie_mountain', 'Saddle Route from Long Meadow', 'scrambling', 'Class 1', 'class', 'Hike in to Long Meadow, leave the trail at an old metal sign and cross the Middle Fork Tule River. Stay just north of the ridge and cut over to the saddle next to point 10,113, then go straight to the summit, avoiding brush.'),
  ('ca_needham_mountain_standard_route', 'ca_needham_mountain', 'Standard route', 'scrambling', 'Class 3', 'class', 'Class 2 to the summit block, which is Class 3.'),
  ('ca_mount_guyot_guyot_pass_route', 'ca_mount_guyot', 'Guyot Pass Route', 'scrambling', 'Class 1', 'class', 'Reach the Pacific Crest Trail near Guyot Pass from Horseshoe Meadow, then climb the sandy slopes to the broad summit plateau. A short blocky summit block needs a few scrambling moves.'),
  ('ca_mount_corcoran_standard_route', 'ca_mount_corcoran', 'Standard route', 'scrambling', 'Class 2', 'class', null),
  ('ca_mount_young_standard_route', 'ca_mount_young', 'Standard route', 'scrambling', 'Class 1', 'class', null),
  ('ca_trojan_peak_standard_route', 'ca_trojan_peak', 'Standard route', 'scrambling', 'Class 2', 'class', null),
  ('ca_lippincott_mountain_standard_route', 'ca_lippincott_mountain', 'Standard route', 'scrambling', 'Class 2', 'class', null),
  ('ca_picket_guard_peak_standard_route', 'ca_picket_guard_peak', 'Standard route', 'scrambling', 'Class 2', 'class', null),
  ('ca_milestone_mountain_standard_route', 'ca_milestone_mountain', 'Standard route', 'scrambling', 'Class 3', 'class', null),
  ('ca_south_guard_south_slope_via_longley_pass', 'ca_south_guard', 'South Slope via Longley Pass', 'scrambling', 'Class 2', 'class', 'Climb the sandy scree to Longley Pass from the Cedar Grove side, then take class 3 rock to the summit, which sits on the west side of the ridge.'),
  ('ca_mount_stanford_south_standard_route', 'ca_mount_stanford_south', 'Standard route', 'scrambling', 'Class 3', 'class', null),
  ('ca_center_peak_standard_route', 'ca_center_peak', 'Standard route', 'mountaineering', 'Class 4', 'class', 'Class 2 to the summit block, which is Class 4.'),
  ('ca_mount_bago_north_ridge', 'ca_mount_bago', 'North Ridge', 'scrambling', 'Class 1', 'class', 'Cross Kearsarge Pass, leave the trail near the Charlotte Lake junction, and go west cross-country into the cirque below the peak. Climb a chute to the easy north ridge and follow it to the summit.'),
  ('ca_colosseum_mountain_standard_route', 'ca_colosseum_mountain', 'Standard route', 'scrambling', 'Class 1', 'class', null),
  ('ca_pyramid_peak_south_standard_route', 'ca_pyramid_peak_south', 'Standard route', 'scrambling', 'Class 2', 'class', null),
  ('ca_mount_ruskin_east_ridge', 'ca_mount_ruskin', 'East Ridge', 'scrambling', 'Class 3', 'class', 'Hike over Taboose Pass and cross the Kings River, then go cross-country to the base of the east ridge. Climb the blocky toe and scramble the ridge, which has exposed class 3 with a move or two harder.'),
  ('ca_kennedy_mountain_standard_route', 'ca_kennedy_mountain', 'Standard route', 'scrambling', 'Class 1', 'class', null),
  ('ca_mount_prater_standard_route', 'ca_mount_prater', 'Standard route', 'scrambling', 'Class 1', 'class', null),
  ('ca_disappointment_peak_standard_route', 'ca_disappointment_peak', 'Standard route', 'mountaineering', 'Class 4', 'class', null),
  ('ca_devils_crag_1_standard_route', 'ca_devils_crag_1', 'Standard route', 'mountaineering', 'Class 4', 'class', null),
  ('ca_charybdis_northeast_ridge', 'ca_charybdis', 'Northeast Ridge', 'scrambling', 'Class 3', 'class', 'From a high camp, follow the south side of the northeast ridge, crossing snow patches and then rock. Near the top a traverse leads to a narrow chute and a notch below the summit monolith.'),
  ('ca_tunemah_peak_east_ridge_via_dykeman_pass', 'ca_tunemah_peak', 'East Ridge via Dykeman Pass', 'scrambling', 'Class 2', 'class', 'Take the Blue Canyon Trail to its north end, continue up to Dykeman Pass, drop into the Alpine Creek drainage and climb talus to the east ridge. The ridge has some class 3 scrambling.'),
  ('ca_mount_huxley_standard_route', 'ca_mount_huxley', 'Standard route', 'scrambling', 'Class 3', 'class', null),
  ('ca_mount_henry_west_ridge', 'ca_mount_henry', 'West Ridge', 'scrambling', 'Class 2', 'class', 'Follow the trail past Post Corral Creek to Fleming and Lower Indian lakes, then go cross-country up grassy slopes to the west ridge and along it to the top. About 2 miles and 2,000 ft past the lake.'),
  ('ca_mount_hooper_southwest_ridge_via_tombstone_pass', 'ca_mount_hooper', 'Southwest Ridge via Tombstone Pass', 'mountaineering', 'Class 4', 'class', 'Follow Tombstone Creek to Tombstone Pass, traverse to the cirque below the summit and climb the southwest ridge to the summit block. The block itself is a short 5.4 crack on the south side. Class 2 to the summit block, which is Class 4.'),
  ('ca_mount_izaak_walton_east_face', 'ca_mount_izaak_walton', 'East Face', 'scrambling', 'Class 2', 'class', 'Hike the Mono Creek trail to Mott Lake, go cross-country to Bighorn Lake, and climb the mostly solid east face. Descend the sandy south face.'),
  ('ca_iron_mountain_via_fern_lake', 'ca_iron_mountain', 'Via Fern Lake', 'scrambling', 'Class 1', 'class', 'Cross the San Joaquin River and take the Mammoth Trail and Beck Lakes Trail to Fern Lake, then climb scree to the ridge and the summit pyramid. About 7 miles each way, partly off-trail.'),
  ('ca_foerster_peak_standard_route', 'ca_foerster_peak', 'Standard route', 'scrambling', 'Class 2', 'class', null),
  ('ca_gray_peak_standard_route', 'ca_gray_peak', 'Standard route', 'scrambling', 'Class 2', 'class', null),
  ('ca_mount_gibbs_standard_route', 'ca_mount_gibbs', 'Standard route', 'scrambling', 'Class 1', 'class', null),
  ('ca_virginia_peak_standard_route', 'ca_virginia_peak', 'Standard route', 'scrambling', 'Class 2', 'class', null),
  ('ca_piute_mountain_northeast_ridge', 'ca_piute_mountain', 'Northeast Ridge', 'scrambling', 'Class 2', 'class', 'A very long trip from Twin Lakes through Kerrick Canyon to Seavey Pass, then up the northeast ridge to a saddle. Drop to a north-side cirque and take a talus chute to the north ridge.'),
  ('ca_disaster_peak_southwest_ridge', 'ca_disaster_peak', 'Southwest Ridge', 'scrambling', 'Class 2', 'class', 'Follow the trail past two meadows to a faint side trail, then leave it near 8,800 ft and go cross-country over sage slopes to the southwest ridge. The summit hump is steep talus.'),
  ('ca_pyramid_peak_north_rocky_canyon', 'ca_pyramid_peak_north', 'Rocky Canyon', 'scrambling', 'Class 2', 'class', 'Follow the Rocky Canyon use trail to the broad area below the south ridge, then climb the ridge to the summit. The trail can be hard to follow where snow lingers.'),
  ('ca_castle_peak_summit_via_castle_pass', 'ca_castle_peak_summit', 'Via Castle Pass', 'scrambling', 'Class 3', 'class', 'Take the Pacific Crest Trail under I-80 to Castle Pass, then follow the ridge northeast to the top of the northwest turret. The last bit is a loose, steep scramble. Class 2 to the summit block, which is Class 3.'),
  ('ca_sierra_buttes_lookout_trail', 'ca_sierra_buttes', 'Lookout Trail', 'scrambling', 'Class 1', 'class', 'A steady trail climbs about 1,500 ft in 2.5 miles, crossing the Pacific Crest Trail. It ends with a long metal staircase up to the lookout.'),
  ('ca_spanish_needle_north_ridge', 'ca_spanish_needle', 'North Ridge', 'scrambling', 'Class 3', 'class', 'Reach the Pacific Crest Trail saddle north of the summit, then climb the north ridge. Expect loose rock, side-hilling and tricky chute-finding on exposed third class.'),
  ('ca_taylor_dome_west_ridge', 'ca_taylor_dome', 'West Ridge', 'scrambling', 'Class 3', 'class', 'Take the Big Meadow Trail to the saddle at the head of Taylor Creek, follow the ridge to the base of the dome, and finish up a short chimney from the saddle. Class 2 to the summit block, which is Class 3.'),
  ('ca_kern_peak_kern_peak_trail_east_face', 'ca_kern_peak', 'Kern Peak Trail (East Face)', 'scrambling', 'Class 1', 'class', 'A long, mostly trail approach through the Kern Plateau meadows leads to a gentle cross-country finish up the east face. Sandy trail sections can be hard to follow.'),
  ('ca_moses_mountain_standard_route', 'ca_moses_mountain', 'Standard route', 'scrambling', 'Class 3', 'class', null),
  ('ca_olancha_peak_via_olancha_pass_and_the_pct', 'ca_olancha_peak', 'Via Olancha Pass and the PCT', 'scrambling', 'Class 2', 'class', 'Climb to Olancha Pass, follow the Pacific Crest Trail north along the west side of the crest, then leave it for the summit. The last stretch is sand, then big granite blocks.'),
  ('ca_joe_devel_peak_standard_route', 'ca_joe_devel_peak', 'Standard route', 'scrambling', 'Class 2', 'class', null),
  ('ca_mount_leconte_east_slope', 'ca_mount_leconte', 'East Slope', 'scrambling', 'Class 3', 'class', 'Follow the Meysan Lake trail, then climb talus to a chute that leads to the plateau and summit. Snow or ice can choke the chute well into summer.'),
  ('ca_mount_hale_standard_route', 'ca_mount_hale', 'Standard route', 'scrambling', 'Class 1', 'class', null),
  ('ca_alta_peak_alta_trail', 'ca_alta_peak', 'Alta Trail', 'scrambling', 'Class 1', 'class', 'A maintained trail climbs from Wolverton through forest to Panther Gap, then across a meadow and past Tharps Rock to switchbacks on the summit. Long day with about 4,000 feet of gain.'),
  ('ca_lion_rock_standard_route', 'ca_lion_rock', 'Standard route', 'scrambling', 'Class 2', 'class', null),
  ('ca_kern_point_standard_route', 'ca_kern_point', 'Standard route', 'scrambling', 'Class 2', 'class', null),
  ('ca_midway_mountain_west_slope', 'ca_midway_mountain', 'West Slope', 'scrambling', 'Class 2', 'class', 'A multi-day approach reaches the Colby Lake area in Cloud Canyon. From there a class 2 slope leads up to the summit.'),
  ('ca_mount_jordan_standard_route', 'ca_mount_jordan', 'Standard route', 'mountaineering', 'Class 4', 'class', 'Class 3 to the summit block, which is Class 4.'),
  ('ca_deerhorn_mountain_northeast_buttress', 'ca_deerhorn_mountain', 'Northeast Buttress', 'scrambling', 'Class 3', 'class', 'Cross Kearsarge Pass, descend to Bubbs Creek, and head up Vidette Creek cross-country. Climb the northeast buttress to the lower northwest summit and traverse to the high point.'),
  ('ca_caltech_peak_standard_route', 'ca_caltech_peak', 'Standard route', 'scrambling', 'Class 2', 'class', null),
  ('ca_black_mountain_sierra_standard_route', 'ca_black_mountain_sierra', 'Standard route', 'scrambling', 'Class 2', 'class', null),
  ('ca_mount_perkins_west_slope', 'ca_mount_perkins', 'West Slope', 'scrambling', 'Class 2', 'class', 'A straightforward class 2 line starts just south of the summit and angles up the west face to a broad gully.'),
  ('ca_striped_mountain_standard_route', 'ca_striped_mountain', 'Standard route', 'scrambling', 'Class 1', 'class', null),
  ('ca_marion_peak_northeast_ridge', 'ca_marion_peak', 'Northeast Ridge', 'scrambling', 'Class 2', 'class', 'Reach Cartridge Pass or Marion Lake, then follow the northeast ridge on class 2 terrain.'),
  ('ca_spanish_mountain_north_ridge', 'ca_spanish_mountain', 'North Ridge', 'scrambling', 'Class 1', 'class', 'Hike the trail past Statham Meadow to the saddle near the Geraldine Lakes, then walk the easy ridge to the summit. The trail is faint in places.'),
  ('ca_mount_bolton_brown_standard_route', 'ca_mount_bolton_brown', 'Standard route', 'scrambling', 'Class 3', 'class', 'Class 2 to the summit block, which is Class 3.'),
  ('ca_palisade_crest_northwest_ridge', 'ca_palisade_crest', 'Northwest Ridge', 'mountaineering', 'Class 4', 'class', 'Take the South Fork Big Pine Creek trail to Elinore Lake, climb to the crest at the notch, and follow the ridge to the high pinnacle. A steep class 4 ramp is the key obstacle.'),
  ('ca_wheel_mountain_standard_route', 'ca_wheel_mountain', 'Standard route', 'scrambling', 'Class 3', 'class', null),
  ('ca_scylla_northwest_slope', 'ca_scylla', 'Northwest Slope', 'scrambling', 'Class 2', 'class', 'A non-technical class 2 ascent from the northwest; long approach via Lamarck Col, the John Muir Trail and Ionian Basin.'),
  ('ca_mount_powell_standard_route', 'ca_mount_powell', 'Standard route', 'scrambling', 'Class 2', 'class', null),
  ('ca_the_hermit_standard_route', 'ca_the_hermit', 'Standard route', 'alpine', 'Class 5', 'class', 'Class 2 to the summit block, which is Class 5.'),
  ('ca_pilot_knob_east_ridge_from_piute_pass', 'ca_pilot_knob', 'East Ridge from Piute Pass', 'scrambling', 'Class 2', 'class', 'Hike over Piute Pass, cross Humphreys Basin to the saddle on the east ridge, then scramble boulders to the summit.'),
  ('ca_mount_hilgard_standard_route', 'ca_mount_hilgard', 'Standard route', 'scrambling', 'Class 2', 'class', null),
  ('ca_red_and_white_mountain_standard_route', 'ca_red_and_white_mountain', 'Standard route', 'scrambling', 'Class 2', 'class', null),
  ('ca_mount_davis_southeast_slopes_from_north_glacier_pass', 'ca_mount_davis', 'Southeast Slopes from North Glacier Pass', 'scrambling', 'Class 2', 'class', 'Walk to Thousand Island Lake and North Glacier Pass, then up easy slopes. The hard part is picking the true summit among bumps.'),
  ('ca_san_joaquin_mountain_san_joaquin_ridge', 'ca_san_joaquin_mountain', 'San Joaquin Ridge', 'scrambling', 'Class 1', 'class', 'Follow the jeep road and use trail north along San Joaquin Ridge, with easy navigation and little elevation gain.'),
  ('ca_mount_florence_standard_route', 'ca_mount_florence', 'Standard route', 'scrambling', 'Class 2', 'class', null),
  ('ca_mount_warren_warren_canyon', 'ca_mount_warren', 'Warren Canyon', 'scrambling', 'Class 1', 'class', 'Follow the creek trail up Warren Canyon, then easy talus to the plateau and a short ridge to the top.'),
  ('ca_twin_peaks_sierra_standard_route', 'ca_twin_peaks_sierra', 'Standard route', 'scrambling', 'Class 2', 'class', null),
  ('ca_black_hawk_mountain_via_summit_creek_and_mosquito_pass', 'ca_black_hawk_mountain', 'Via Summit Creek and Mosquito Pass', 'scrambling', 'Class 2', 'class', 'Follow Summit Creek trail about 10 miles to Lunch Meadow, leave the trail before Mosquito Pass, and climb a drainage to the summit ridge.'),
  ('ca_highland_peak_via_noble_lake', 'ca_highland_peak', 'Via Noble Lake', 'scrambling', 'Class 2', 'class', 'Follow the Pacific Crest Trail to Noble Lake, then a use trail to the saddle and class 2 sand to the summits.'),
  ('ca_dicks_peak_standard_route', 'ca_dicks_peak', 'Standard route', 'scrambling', 'Class 2', 'class', null),
  ('nv_mount_rose_mount_rose_trail', 'nv_mount_rose', 'Mount Rose Trail', 'scrambling', 'Class 1', 'class', 'A well-defined trail from the highway pass climbs about 2,000 feet over roughly five miles to a saddle and the summit.'),
  ('ca_mount_elwell_mt_elwell_trail', 'ca_mount_elwell', 'Mt. Elwell Trail', 'scrambling', 'Class 1', 'class', 'A trail leads up from the Lakes Basin to the summit. Other access points also exist.'),
  ('ca_lamont_peak_lamont_peak_trail', 'ca_lamont_peak', 'Lamont Peak Trail', 'scrambling', 'Class 2', 'class', 'A short, steep trail climbs the ridge from the Canebrake Road saddle, fades in places, then follows cairns up the final ridge to the summit rocks. Expect a bit of scrambling and boulder hopping near the top.'),
  ('ca_sirretta_peak_standard_route', 'ca_sirretta_peak', 'Standard route', 'scrambling', 'Class 1', 'class', null),
  ('ca_angora_mountain_standard_route', 'ca_angora_mountain', 'Standard route', 'scrambling', 'Class 2', 'class', null),
  ('ca_homers_nose_standard_route', 'ca_homers_nose', 'Standard route', 'scrambling', 'Class 1', 'class', null),
  ('ca_cartago_peak_standard_route', 'ca_cartago_peak', 'Standard route', 'scrambling', 'Class 3', 'class', 'Class 2 to the summit block, which is Class 3.'),
  ('ca_mount_pickering_standard_route', 'ca_mount_pickering', 'Standard route', 'scrambling', 'Class 2', 'class', null),
  ('ca_mount_mallory_east_slopes_from_meysan_lake', 'ca_mount_mallory', 'East Slopes from Meysan Lake', 'scrambling', 'Class 2', 'class', 'Hike the Meysan Lakes trail to the lake, then climb the loose gully near the south side of the east ridge to the plateau and the summit blocks. Scree and talus all the way.'),
  ('ca_tunnabora_peak_south_slope_from_tulainyo_lake', 'ca_tunnabora_peak', 'South Slope from Tulainyo Lake', 'scrambling', 'Class 2', 'class', 'Climb the Mountaineers Route to the Russell-Carillon plateau, cross the Russell-Carillon pass (class 3 on the north side) to Tulainyo Lake, then walk the sandy south slopes to the summit.'),
  ('ca_mount_silliman_south_slope_from_silliman_lake', 'ca_mount_silliman', 'South Slope from Silliman Lake', 'scrambling', 'Class 1', 'class', 'Follow the Twin Lakes trail to Silliman Creek, go up the creek to Silliman Meadow and the friction slabs to Silliman Lake. Continue to the upper lake and climb the south slope to the summit.'),
  ('ca_mount_kaweah_standard_route', 'ca_mount_kaweah', 'Standard route', 'scrambling', 'Class 2', 'class', null),
  ('ca_triple_divide_peak_standard_route', 'ca_triple_divide_peak', 'Standard route', 'scrambling', 'Class 2', 'class', null),
  ('ca_table_mountain_sierra_southeast_face_ramp', 'ca_table_mountain_sierra', 'Southeast Face Ramp', 'scrambling', 'Class 3', 'class', 'Cross Shepherd Pass, drop to the Kern, and climb Milestone Basin to the base of the southeast face. A prominent ramp leads up the left side to a keyhole and the summit plateau, with the high point at its north end.'),
  ('ca_mount_genevra_standard_route', 'ca_mount_genevra', 'Standard route', 'scrambling', 'Class 2', 'class', null),
  ('ca_west_vidette_standard_route', 'ca_west_vidette', 'Standard route', 'scrambling', 'Class 2', 'class', null),
  ('ca_kearsarge_peak_standard_route', 'ca_kearsarge_peak', 'Standard route', 'scrambling', 'Class 1', 'class', null),
  ('ca_diamond_peak_standard_route', 'ca_diamond_peak', 'Standard route', 'scrambling', 'Class 2', 'class', null),
  ('ca_mount_wynne_standard_route', 'ca_mount_wynne', 'Standard route', 'scrambling', 'Class 2', 'class', null),
  ('ca_goodale_mountain_west_side_from_taboose_pass', 'ca_goodale_mountain', 'West Side from Taboose Pass', 'scrambling', 'Class 3', 'class', 'Climb the Taboose Pass trail, go into the basin left of the summit ridge, and reach the saddle between Goodale and Striped Mountains. Scramble the steep slope to the southern pinnacle; only the last 20 ft are third class. Class 2 to the summit block, which is Class 3.'),
  ('ca_state_peak_standard_route', 'ca_state_peak', 'Standard route', 'scrambling', 'Class 2', 'class', null),
  ('ca_three_sisters_standard_route', 'ca_three_sisters', 'Standard route', 'scrambling', 'Class 1', 'class', null),
  ('ca_birch_mountain_standard_route', 'ca_birch_mountain', 'Standard route', 'scrambling', 'Class 2', 'class', null),
  ('ca_observation_peak_standard_route', 'ca_observation_peak', 'Standard route', 'scrambling', 'Class 2', 'class', null),
  ('ca_mount_mcduffie_standard_route', 'ca_mount_mcduffie', 'Standard route', 'scrambling', 'Class 2', 'class', null),
  ('ca_mount_goddard_standard_route', 'ca_mount_goddard', 'Standard route', 'scrambling', 'Class 2', 'class', null),
  ('ca_mount_wallace_standard_route', 'ca_mount_wallace', 'Standard route', 'mountaineering', 'Class 4', 'class', 'Class 2 to the summit block, which is Class 4.'),
  ('ca_mount_mcgee_standard_route', 'ca_mount_mcgee', 'Standard route', 'scrambling', 'Class 3', 'class', null),
  ('ca_gemini_standard_route', 'ca_gemini', 'Standard route', 'scrambling', 'Class 2', 'class', null),
  ('ca_recess_peak_standard_route', 'ca_recess_peak', 'Standard route', 'scrambling', 'Class 2', 'class', null),
  ('ca_mount_stanford_north_standard_route', 'ca_mount_stanford_north', 'Standard route', 'scrambling', 'Class 2', 'class', null),
  ('ca_rodgers_peak_standard_route', 'ca_rodgers_peak', 'Standard route', 'scrambling', 'Class 2', 'class', null),
  ('ca_merced_peak_standard_route', 'ca_merced_peak', 'Standard route', 'scrambling', 'Class 2', 'class', null),
  ('ca_mount_maclure_standard_route', 'ca_mount_maclure', 'Standard route', 'scrambling', 'Class 3', 'class', null),
  ('ca_excelsior_mountain_standard_route', 'ca_excelsior_mountain', 'Standard route', 'scrambling', 'Class 1', 'class', null),
  ('ca_pettit_peak_standard_route', 'ca_pettit_peak', 'Standard route', 'scrambling', 'Class 2', 'class', null),
  ('ca_leavitt_peak_pacific_crest_trail_and_east_shoulder', 'ca_leavitt_peak', 'Pacific Crest Trail and East Shoulder', 'scrambling', 'Class 1', 'class', 'Follow the PCT south from Sonora Pass, leave it at a notch on the ridge, and continue up the talus ridge to the broad summit area.'),
  ('ca_mokelumne_peak_standard_route', 'ca_mokelumne_peak', 'Standard route', 'scrambling', 'Class 2', 'class', null),
  ('ca_granite_chief_granite_chief_trail_from_olympic_valley', 'ca_granite_chief', 'Granite Chief Trail from Olympic Valley', 'scrambling', 'Class 1', 'class', 'Take the trail from behind the fire station along the ski area boundary to the Pacific Crest Trail, then follow the northeast ridge to the summit.'),
  ('ca_mount_lola_lola_trail', 'ca_mount_lola', 'Lola Trail', 'scrambling', 'Class 1', 'class', 'A well-defined trail climbs through forest and Cold Stream Meadow toward the south ridge and summit. Easy and non-technical.'),
  ('ca_adams_peak_standard_route', 'ca_adams_peak', 'Standard route', 'scrambling', 'Class 2', 'class', null),
  ('ca_sawtooth_peak_sierra_standard_route', 'ca_sawtooth_peak_sierra', 'Standard route', 'scrambling', 'Class 2', 'class', null),
  ('ca_crag_peak_via_clover_meadow', 'ca_crag_peak', 'Via Clover Meadow', 'scrambling', 'Class 3', 'class', 'Follow the Pacific Crest Trail north about five miles to Clover Meadow, then leave it and climb roughly 3,000 ft west through dense manzanita to the ridge. The true highpoint is the northern rock group, a short distance beyond the lower southern summit, with some class 3 on the ridge.'),
  ('ca_coyote_peaks_via_coyote_pass_and_the_saddle', 'ca_coyote_peaks', 'Via Coyote Pass and the Saddle', 'scrambling', 'Class 2', 'class', 'A very long approach: from the trailhead go over Farewell Gap, south along the trail to Coyote Pass, then cross-country to the saddle between the two summits. A short boulder scramble finishes the climb. Water can be scarce on the trail.'),
  ('ca_vandever_mountain_south_slope_from_farewell_gap', 'ca_vandever_mountain', 'South Slope from Farewell Gap', 'scrambling', 'Class 1', 'class', 'Hike to Farewell Gap, then climb the talus slope on the west side of the gap to the summit. Easy class 2 and commonly done as a day trip.'),
  ('ca_muah_mountain_via_mulkey_pass', 'ca_muah_mountain', 'Via Mulkey Pass', 'scrambling', 'Class 2', 'class', 'From Horseshoe Meadow climb to Mulkey Pass, then follow the crest trail south and leave it for a cross-country climb through foxtail pines and talus to the summit rocks. About 12 miles round trip with roughly 2,900 ft of gain.'),
  ('ca_mount_newcomb_southwest_slope', 'ca_mount_newcomb', 'Southwest Slope', 'scrambling', 'Class 2', 'class', 'The easy side is the southwest slope above the Crabtree Lakes. A common long approach crosses Discovery Pass and Crabtree Pass; the ridge from Crabtree Pass is slower and reaches class 3.'),
  ('ca_mount_mcadie_via_arc_pass', 'ca_mount_mcadie', 'Via Arc Pass', 'scrambling', 'Class 3', 'class', 'Reach Arc Pass, then climb scree and talus to the south summit. Downclimb a class 3 step into the notch, go up a short way and follow a ramp left onto easy scrambling to the highest point. Exposed; a rope may be welcome.'),
  ('ca_mount_barnard_standard_route', 'ca_mount_barnard', 'Standard route', 'scrambling', 'Class 2', 'class', null),
  ('ca_mount_eisen_southeast_ridge_from_black_rock_pass', 'ca_mount_eisen', 'Southeast Ridge from Black Rock Pass', 'scrambling', 'Class 2', 'class', 'Cross Glacier Pass and descend toward Cliff Creek, climb to Black Rock Pass, then traverse the ridge to the saddle at the base of the southeast ridge. Follow the ridge to the summit; long and tedious rather than hard.'),
  ('ca_red_kaweah_west_face', 'ca_red_kaweah', 'West Face', 'scrambling', 'Class 3', 'class', 'Reach the cirque of lakes between Black and Red Kaweah from Big Arroyo, then climb the broad west face on loose talus and boulders, keeping well right of Black Kaweah''s face. The crest is gained just below the summit; the rock is very unstable. Class 2 to the summit block, which is Class 3.'),
  ('ca_glacier_ridge_standard_route', 'ca_glacier_ridge', 'Standard route', 'mountaineering', 'Class 4', 'class', 'Class 2 to the summit block, which is Class 4.'),
  ('ca_thunder_mountain_sierra_thunder_col_and_east_ridge', 'ca_thunder_mountain_sierra', 'Thunder Col and East Ridge', 'mountaineering', 'Class 4', 'class', 'Go up the Bubbs Creek and East Lake drainages past Lake Reflection to the lakes below Thunder Col, then climb the east ridge or southeast slopes. The summit crux is a short exposed move on the north summit block. Class 3 to the summit block, which is Class 4.'),
  ('ca_mount_ericsson_west_ridge_from_lucys_foot_pass', 'ca_mount_ericsson', 'West Ridge from Lucys Foot Pass', 'scrambling', 'Class 2', 'class', 'Approach via the Bubbs Creek and East Lake drainage to Lake Reflection and the chute leading to Lucys Foot Pass, then scramble the west ridge to the summit. A multi-day trip with exposed, loose terrain near the top.'),
  ('ca_mount_bradley_standard_route', 'ca_mount_bradley', 'Standard route', 'scrambling', 'Class 2', 'class', null),
  ('ca_mount_rixford_south_slope', 'ca_mount_rixford', 'South Slope', 'scrambling', 'Class 2', 'class', 'Hike over Kearsarge Pass to the Bullfrog Lake area, then climb the loose scree and talus slopes to the summit ridge. The last few hundred feet are steeper, with a few easy moves on dark rock near the top.'),
  ('ca_mount_baxter_standard_route', 'ca_mount_baxter', 'Standard route', 'scrambling', 'Class 2', 'class', null),
  ('ca_mount_pinchot_east_ridge_from_armstrong_canyon', 'ca_mount_pinchot', 'East Ridge from Armstrong Canyon', 'scrambling', 'Class 2', 'class', 'Climb the loose talus chute out of Armstrong Canyon to the crest, cross the high basin, and follow the talus of the east ridge to the summit. Water is scarce and the chute is loose.'),
  ('ca_cardinal_mountain_via_taboose_pass', 'ca_cardinal_mountain', 'Via Taboose Pass', 'scrambling', 'Class 2', 'class', 'Hike the Taboose Pass trail about eight miles to the pass, then climb the peak about a mile to the north. The south chute is loose; the solid rock nose to its right is a more pleasant way up.'),
  ('ca_goat_mountain_via_grouse_lake_and_northwest_ridge', 'ca_goat_mountain', 'Via Grouse Lake and Northwest Ridge', 'scrambling', 'Class 2', 'class', 'Follow the Copper Creek Trail to the Granite Basin area, then go cross-country to Grouse Lake. Climb to the saddle between Munger Peak and Goat, then follow the northwest ridge to the summit. Long day with a lot of gain.'),
  ('ca_mount_tinemaha_south_slope_from_red_lake', 'ca_mount_tinemaha', 'South Slope from Red Lake', 'scrambling', 'Class 2', 'class', 'Hike the trail to Red Lake, then go up the bowl south of the peak on boulders and talus to the summit. Early season can bring a steep snow chute in the upper bowl.'),
  ('ca_the_thumb_southeast_slope_from_birch_lake', 'ca_the_thumb', 'Southeast Slope from Birch Lake', 'scrambling', 'Class 2', 'class', 'Follow the Birch Creek trail to Birch Lake, climb the steep ramp west of the lake to the crest, then ascend talus and snow to the summit. The ramp holds snow into summer and may need crampons.'),
  ('ca_giraud_peak_standard_route', 'ca_giraud_peak', 'Standard route', 'scrambling', 'Class 2', 'class', null),
  ('ca_black_giant_west_slope_from_black_giant_pass', 'ca_black_giant', 'West Slope from Black Giant Pass', 'scrambling', 'Class 1', 'class', 'A remote peak reached off the John Muir Trail near Muir Pass; leave the trail for Black Giant Pass, then walk up about half a mile of loose rock to the summit. The east-side approach over Echo Col from Lake Sabrina adds class 3 and possible snow.'),
  ('ca_mount_reinstein_standard_route', 'ca_mount_reinstein', 'Standard route', 'scrambling', 'Class 2', 'class', null),
  ('ca_mount_fiske_standard_route', 'ca_mount_fiske', 'Standard route', 'scrambling', 'Class 2', 'class', null),
  ('ca_emerald_peak_west_gully_to_north_ridge', 'ca_emerald_peak', 'West Gully to North Ridge', 'scrambling', 'Class 2', 'class', 'Reach the Evolution Meadow area via the John Muir Trail, then climb the broad west-face gully to the north ridge and follow it to the top. Rock is loose; exit the gully to the south after the second tower to avoid class 3.'),
  ('ca_mount_senger_via_sallie_keyes_lakes', 'ca_mount_senger', 'Via Sallie Keyes Lakes', 'scrambling', 'Class 2', 'class', 'Hike the trail around Florence Lake and across the San Joaquin, take the cutoff use trail toward Selden Pass, and climb to Sallie Keyes Lakes. Continue over boulders and a bench below the summit; the final slopes are easier than they look.'),
  ('ca_silver_peak_standard_route', 'ca_silver_peak', 'Standard route', 'scrambling', 'Class 2', 'class', null),
  ('ca_mount_baldwin_via_convict_canyon_and_bright_dot_lake', 'ca_mount_baldwin', 'Via Convict Canyon and Bright Dot Lake', 'scrambling', 'Class 2', 'class', 'Follow the trail up from Convict Lake to Bright Dot Lake, then a use trail up the steep sand and gravel above it to the summit. About 13 miles round trip with roughly 5,000 ft of gain.'),
  ('ca_electra_peak_standard_route', 'ca_electra_peak', 'Standard route', 'scrambling', 'Class 2', 'class', null),
  ('ca_red_peak_standard_route', 'ca_red_peak', 'Standard route', 'scrambling', 'Class 2', 'class', null),
  ('ca_koip_peak_via_parker_pass_and_koip_peak_pass', 'ca_koip_peak', 'Via Parker Pass and Koip Peak Pass', 'scrambling', 'Class 1', 'class', 'Follow the Mono Pass trail to the Parker Pass junction, cross Parker Pass, and climb switchbacks on Parker Peak''s north flank to Koip Peak Pass. From there, a short walk-up over talus leads to the summit.'),
  ('ca_dunderberg_peak_southeast_slopes_from_virginia_lakes', 'ca_dunderberg_peak', 'Southeast Slopes from Virginia Lakes', 'scrambling', 'Class 2', 'class', 'Leave the parking area cross-country up the southeast slopes, cross low scrub, then slog talus to the broad plateau and the summit. Easy terrain overall but the talus is loose.'),
  ('ca_volunteer_peak_standard_route', 'ca_volunteer_peak', 'Standard route', 'scrambling', 'Class 2', 'class', null),
  ('ca_stanislaus_peak_southeast_face_from_st_marys_pass', 'ca_stanislaus_peak', 'Southeast Face from St. Marys Pass', 'scrambling', 'Class 1', 'class', 'Take the trail to St. Marys Pass, then north along the broad ridge until the trail fades at the saddle before the peak. Climb the south face of dirt, sand and scree, with some class 2 rock near the top.'),
  ('ca_freel_peak_south_ridge_via_tahoe_rim_trail', 'ca_freel_peak', 'South Ridge via Tahoe Rim Trail', 'scrambling', 'Class 1', 'class', 'Hike up toward Armstrong Pass, join the Tahoe Rim Trail, and follow the Freel Peak trail up the sandy ridge to the summit. Several trail approaches exist, all non-technical.'),
  ('ca_tinker_knob_via_the_pacific_crest_trail', 'ca_tinker_knob', 'Via the Pacific Crest Trail', 'scrambling', 'Class 1', 'class', 'Reach the Pacific Crest Trail and follow it to the saddle just southeast of the peak, then walk a short distance to the summit. A longer, easier approach comes along the crest trail from Donner Pass.'),
  ('ca_english_mountain_standard_route', 'ca_english_mountain', 'Standard route', 'scrambling', 'Class 2', 'class', null)
